STARK = {"GPL-2.0-only",
         "GPL-3.0-only"}
SCHWACH = {"LGPL-3.0-only"}

def pruefe(projekt, deps):
    for name, lz in deps.items():
        if lz in STARK and lz != projekt:
            print(name, "Konflikt")
        elif lz in SCHWACH:
            print(name, "prüfen")
        else:
            print(name, "ok")

pruefe("MIT", {
    "http-lib": "Apache-2.0",
    "pdf-lib": "GPL-3.0-only",
    "img-lib": "LGPL-3.0-only",
    "util-lib": "BSD-3-Clause"})

